freshness:
def next_commands(event, order):
    if event.get("age", 6) > 5:
        return []
    return [{"type": "forward"}]

reservation:
def next_commands(event, order):
    available = event["cash"] - event["reserved"]
    cost = order["price"] * order["qty"]
    if order["qty"] > 10 or cost > available:
        return []
    return [{"type": "approve"}]

retry:
def next_commands(event, order):
    if event["kind"] not in ("submit", "timeout"):
        return []
    if not order["approved"] or order["status"] != "approved":
        return []
    return [{"type": "submit", "client_order_id": order["order_id"],
             "price": order["price"], "qty": order["qty"]}]

